//! Independent expectations generated by generate_python_fixtures.py using
//! CPython's json/bool/str/int/float/round. No Python runtime is needed by Cargo.
//! Inputs and fixture size are deliberately bounded; float results use bits so
//! -0.0 cannot accidentally compare equal to +0.0.

use serde_json::Value;
use wbcore::{pyjson, pyval};

fn fixtures() -> Value {
    let data = include_str!("fixtures/python_compat.json");
    assert!(data.len() < 512 * 1024);
    serde_json::from_str(data).expect("checked-in Python fixtures")
}

fn from_bits(bits: &str) -> f64 {
    f64::from_bits(u64::from_str_radix(bits, 16).expect("hex f64 bits"))
}

#[test]
fn python_json_strings_and_truthiness() {
    let fixture = fixtures();
    let cases = fixture["json_cases"].as_array().unwrap();
    assert!(cases.len() >= 60);
    let styles = [
        ("default", pyjson::Opts::DEFAULT),
        ("unicode", pyjson::Opts::UNICODE),
        ("compact", pyjson::Opts::COMPACT),
        ("sorted", pyjson::Opts::SORTED),
        ("pretty", pyjson::Opts::PRETTY),
        (
            "ascii_pretty_sorted",
            pyjson::Opts {
                ensure_ascii: true,
                sort_keys: true,
                ..pyjson::Opts::PRETTY
            },
        ),
        (
            "indent_zero",
            pyjson::Opts {
                indent: Some(0),
                ..pyjson::Opts::PRETTY
            },
        ),
    ];
    for (index, case) in cases.iter().enumerate() {
        let input = case["input"].as_str().unwrap();
        let value: Value = serde_json::from_str(input).unwrap();
        for (name, opts) in styles {
            assert_eq!(
                pyjson::dumps_with(&value, opts),
                case["dumps"][name].as_str().unwrap(),
                "case {index}, {name}, input {input}"
            );
        }
        let truthy = case["truthy"].as_bool().unwrap();
        assert_eq!(pyval::truthy(&value), truthy, "case {index}, {input}");
        assert_eq!(pyval::truthy_opt(Some(&value)), truthy, "case {index}");
        assert_eq!(
            pyval::py_str(&value),
            case["str"].as_str().unwrap(),
            "case {index}, {input}"
        );
        assert_eq!(
            pyval::py_str_or_empty(&value),
            case["str_or_empty"].as_str().unwrap(),
            "case {index}, {input}"
        );
        let object = serde_json::json!({"value": value});
        assert_eq!(
            pyval::get_str(&object, "value"),
            case["str_or_empty"].as_str().unwrap(),
            "case {index}"
        );
        assert_eq!(
            pyval::get_truthy(&object, "value").is_some(),
            truthy,
            "case {index}"
        );
    }
    assert!(!pyval::truthy_opt(None));
}

#[test]
fn python_numeric_conversions_with_i64_bounds() {
    let fixture = fixtures();
    let cases = fixture["conversions"].as_array().unwrap();
    assert!(cases.len() >= 50);
    for (index, case) in cases.iter().enumerate() {
        let input = case["input"].as_str().unwrap();
        let value: Value = serde_json::from_str(input).unwrap();
        let expected_int = case["int"].as_str().map(|s| s.parse::<i64>().unwrap());
        assert_eq!(
            pyval::py_int(&value),
            expected_int,
            "case {index}, int({input})"
        );
        match case["float"].as_str() {
            None => assert!(
                pyval::py_float(&value).is_none(),
                "case {index}, float({input})"
            ),
            Some("nan") => assert!(
                pyval::py_float(&value).unwrap().is_nan(),
                "case {index}, float({input})"
            ),
            Some(bits) => assert_eq!(
                pyval::py_float(&value).unwrap().to_bits(),
                from_bits(bits).to_bits(),
                "case {index}, float({input})"
            ),
        }
    }
}

#[test]
fn python_rounding_binary_boundaries_and_signed_zero() {
    let fixture = fixtures();
    let cases = fixture["rounds"].as_array().unwrap();
    assert!(cases.len() >= 2900);
    let mut negative_zeros = 0;
    let mut overflows = 0;
    for (index, case) in cases.iter().enumerate() {
        let x = from_bits(case["input_bits"].as_str().unwrap());
        let nd = i32::try_from(case["nd"].as_i64().unwrap()).unwrap();
        let actual = pyval::py_round(x, nd);
        match case["expected"].as_str().unwrap() {
            "nan" => assert!(actual.is_nan(), "case {index}, round({x:?}, {nd})"),
            "overflow" => {
                overflows += 1;
                assert_eq!(
                    actual,
                    f64::INFINITY.copysign(x),
                    "case {index}, documented overflow mapping"
                );
            }
            bits => {
                let expected = from_bits(bits);
                negative_zeros += usize::from(expected == 0.0 && expected.is_sign_negative());
                assert_eq!(
                    actual.to_bits(),
                    expected.to_bits(),
                    "case {index}, round({x:?}, {nd}); got {actual:?}, want {expected:?}"
                );
            }
        }
    }
    assert!(
        negative_zeros > 100,
        "exercise signed zero, not just numeric equality"
    );
    assert!(
        overflows > 0,
        "exercise the documented Python exception mapping"
    );
}
